import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { useAsyncDebouncer } from "@tanstack/react-pacer/async-debouncer";
import type { ComponentProps } from "react";
import { StatefulButton } from "@/registry/erbium/ui/stateful-button";

export const AsyncStatefulButton = ({
  children,
  successLabel,
  variant,
}: {
  children: string;
  successLabel: string;
  variant?: ComponentProps<typeof StatefulButton>["variant"];
}) => {
  const request = useAsyncDebouncer(async () => {}, { wait: 1200 });

  return (
    <StatefulButton
      variant={variant}
      onClick={async () => {
        await request.maybeExecute();
      }}
      successLabel={successLabel}
    >
      {children}
    </StatefulButton>
  );
};

const StatefulButtonDemo = () => (
  <div className="flex flex-wrap items-center gap-3">
    <AsyncStatefulButton successLabel="Saved">Save</AsyncStatefulButton>
    <AsyncStatefulButton successLabel="Updated" variant="outline">
      Update
    </AsyncStatefulButton>
  </div>
);

export default StatefulButtonDemo;

import { Effect, Schema } from "effect";
import { Form, useAppForm } from "@/registry/erbium/ui/form";

const Subscription = Schema.toStandardSchemaV1(
  Schema.Struct({
    email: Schema.String.check(
      Schema.isPattern(/^[^\s@]+@[^\s@]+\.[^\s@]+$/u, { message: "Enter a valid email address." }),
    ),
  }),
);

export default function StatefulButtonFormExample() {
  const form = useAppForm({
    defaultValues: { email: "" },
    onSubmit: async () => {
      // Stands in for the request that subscribes the address.
      await Effect.runPromise(Effect.sleep("1200 millis"));
    },
    validators: { onDynamic: Subscription },
  });

  return (
    <Form form={form} className="w-80 space-y-4">
      <form.AppField name="email">
        {(field) => <field.TextField label="Email" required type="email" autoComplete="email" />}
      </form.AppField>
      <form.SubmitButton successLabel="Subscribed">Subscribe</form.SubmitButton>
    </Form>
  );
}

